class Solution:
    def countQuadruples(self, firstString: str, secondString: str) -> int:
        best = 10 ** 9
        count = 0
        for i, c1 in enumerate(firstString):
            for a, c2 in enumerate(secondString):
                if c1 == c2:
                    diff = i - a
                    if diff < best:
                        best = diff
                        count = 1
                    elif diff == best:
                        count += 1
        return count

