class Solution {
public:
    int countQuadruples(string firstString, string secondString) {
        vector<int> firstPos(26, -1), lastPos(26, -1);
        for (int i = 0; i < (int)firstString.size(); i++) {
            int c = firstString[i] - 'a';
            if (firstPos[c] == -1) firstPos[c] = i;
        }
        for (int a = 0; a < (int)secondString.size(); a++)
            lastPos[secondString[a] - 'a'] = a;
        int best = INT_MAX, count = 0;
        for (int c = 0; c < 26; c++) {
            if (firstPos[c] == -1 || lastPos[c] == -1) continue;
            int diff = firstPos[c] - lastPos[c];
            if (diff < best) { best = diff; count = 1; }
            else if (diff == best) count++;
        }
        return count;
    }
};

