    const firstPos = new Array(26).fill(-1);
    const lastPos = new Array(26).fill(-1);
    for (let i = 0; i < firstString.length; i++) {
        const c = firstString.charCodeAt(i) - 97;
        if (firstPos[c] === -1) firstPos[c] = i;
    }
    for (let a = 0; a < secondString.length; a++)
        lastPos[secondString.charCodeAt(a) - 97] = a;
    let best = Infinity, count = 0;
    for (let c = 0; c < 26; c++) {
        if (firstPos[c] === -1 || lastPos[c] === -1) continue;
        const diff = firstPos[c] - lastPos[c];
        if (diff < best) { best = diff; count = 1; }
        else if (diff === best) count++;
    }
    return count;
};
